import React, { useState, useEffect } from 'react';

function BookingForm({ slot, onBooked }) {
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [cost, setCost] = useState(0);

  useEffect(() => {
    if (startTime && endTime && slot?.hourlyRate) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffMs = end - start;

      if (diffMs > 0) {
        const hours = Math.ceil(diffMs / (1000 * 60 * 60));
        setCost(hours * slot.hourlyRate);
      } else {
        setCost(0);
      }
    }
  }, [startTime, endTime, slot]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const now = new Date();
    const gracePeriodInMs = 60 * 1000; // 1 minute

    if (new Date(startTime) - now < -gracePeriodInMs) {
      alert('Start time cannot be in the past');
      return;
    }

    if (new Date(endTime) <= new Date(startTime)) {
      alert('End time must be after start time');
      return;
    }

    const bookingData = {
      slotId: slot.id,
      vehicleNumber,
      startTime,
      endTime,
      cost,
    };

    try {
      const response = await fetch('http://localhost:8080/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bookingData),
      });

      if (response.ok) {
        const savedBooking = await response.json();
        onBooked(savedBooking);
      } else {
        alert('Failed to book slot');
      }
    } catch (error) {
      console.error(error);
      alert('Error occurred while booking');
    }
  };

  if (!slot) return <p>Loading slot details...</p>;

  return (
    <div>
      <h2>Book Slot {slot.slotNumber}</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Vehicle Number:</label>
          <input
            type="text"
            value={vehicleNumber}
            onChange={(e) => setVehicleNumber(e.target.value)}
            required
          />
        </div>
        <div>
          <label>Start Time:</label>
          <input
            type="datetime-local"
            value={startTime}
            onChange={(e) => setStartTime(e.target.value)}
            required
          />
        </div>
        <div>
          <label>End Time:</label>
          <input
            type="datetime-local"
            value={endTime}
            onChange={(e) => setEndTime(e.target.value)}
            required
          />
        </div>
        <div>
          <strong>Estimated Cost: ${cost.toFixed(2)}</strong>
        </div>
        <button type="submit">Book</button>
      </form>
    </div>
  );
}

export default BookingForm;
